record UpdateProfileRequest(@NotBlank @Size(max = 100) String displayName,
                            @NotBlank @Email String email) {}

record ProfileResponse(Long id, String displayName, String email) {
    static ProfileResponse from(User user) {
        return new ProfileResponse(user.getId(), user.getDisplayName(), user.getEmail());
    }
}

@RestController
class ProfileController {
    private final ProfileService profiles;

    ProfileController(ProfileService profiles) { this.profiles = profiles; }

    @PutMapping("/api/users/{id}/profile")
    ProfileResponse update(@PathVariable Long id, @Valid @RequestBody UpdateProfileRequest request) {
        return profiles.update(id, request);
    }
}

@Service
class ProfileService {
    private final UserRepository users;

    ProfileService(UserRepository users) { this.users = users; }

    @Transactional
    ProfileResponse update(Long id, UpdateProfileRequest request) {
        User user = users.findById(id).orElseThrow(() -> new UserNotFoundException(id));
        user.changeProfile(request.displayName(), request.email());   // chỉ hai field được phép đổi
        return ProfileResponse.from(user);                            // dirty checking ghi khi commit
    }
}
